/** Browser-safe request-body templates shared by the IDE and generated applications. */
export const WEB_API_TEMPLATE_PARAMETER_TYPES: readonly [
    "string",
    "number",
    "integer",
    "boolean",
    "object",
    "array",
    "null"
];

export type WebApiTemplateParameterType = (typeof WEB_API_TEMPLATE_PARAMETER_TYPES)[number];

export interface WebApiTemplateParameter {
    readonly name: string;
    readonly type: WebApiTemplateParameterType;
}

export type WebApiTemplateValue = string | number | boolean | null | readonly WebApiTemplateValue[] | {
    readonly [key: string]: WebApiTemplateValue;
};

export type WebApiTemplateValues = Readonly<Record<string, WebApiTemplateValue>>;

/** Derives unique names from the template and preserves existing type choices by name. */
export function getApiClientTemplateParameters(content: string, existing?: readonly WebApiTemplateParameter[]): readonly WebApiTemplateParameter[];

/** Converts an IDE-only input into a typed value without evaluating source code. */
export function parseApiClientTemplateTestValue(parameter: WebApiTemplateParameter, input: string): WebApiTemplateValue;

/** Resolves a body template while preserving JSON types and escaping string contents. */
export function resolveApiClientBodyTemplate(body: WebApiRequestBody, values?: WebApiTemplateValues): string;

export interface WebApiBodyInput extends WebApiTemplateParameter {
    readonly required: boolean;
    readonly inferred: boolean;
    readonly defaultValue?: WebApiTemplateValue;
}

/** Public reflection uses the same persisted body for code generation and runtime parameters. */
export function getApiClientBodyInputs(body: WebApiRequestBody): readonly WebApiBodyInput[];

/** Validates/copies input data while preventing prototype fields and unserializable values. */
export function copyApiClientInput(value: WebApiTemplateValue): WebApiTemplateValue;

export type WebApiQueryValue = QueryValue | readonly QueryValue[];

export type WebApiParameterValue = WebApiTemplateValue | readonly QueryValue[];

export type WebApiParameterValues<T extends object> = {
    -readonly [K in keyof T]?: T[K];
};

export type WebApiQueryValues<T extends object = Record<string, WebApiQueryValue>> = WebApiParameterValues<T> & Record<string, WebApiQueryValue>;

export type WebApiHeaderValues<T extends object = Record<string, string>> = WebApiParameterValues<T> & Record<string, string | undefined>;

/** Generated inputs preserve the configured names without an untyped component namespace. */
export interface WebApiRequestInputs {
    readonly Parameter: object;
    readonly Query: object;
    readonly Headers: object;
}

export interface WebApiDefaultInputs extends WebApiRequestInputs {
    readonly Parameter: Record<string, WebApiParameterValue>;
    readonly Query: Record<string, WebApiQueryValue>;
    readonly Headers: Record<string, string>;
}

export type WebApiInputPart<T, K extends keyof WebApiRequestInputs> = T extends {
    readonly [P in K]: infer Values extends object;
} ? Values : Record<string, K extends 'Headers' ? string : WebApiTemplateValue>;

export type WebApiInputUnion<T extends object, K extends keyof WebApiRequestInputs> = WebApiInputPart<T[keyof T], K>;

export type WebApiUnionKeys<T> = T extends object ? keyof T : never;

export type WebApiUnionValue<T, K extends PropertyKey> = T extends object ? K extends keyof T ? T[K] : never : never;

export type WebApiCombinedInputs<T extends object, K extends keyof WebApiRequestInputs> = {
    [P in WebApiUnionKeys<WebApiInputUnion<T, K>>]: WebApiUnionValue<WebApiInputUnion<T, K>, P>;
};

export type WebApiRequests<TOutputs extends object, TInputs extends object> = {
    readonly [K in keyof TOutputs & string]: WebApiRequest<WebApiInputPart<K extends keyof TInputs ? TInputs[K] : WebApiDefaultInputs, 'Parameter'>, TOutputs[K], WebApiInputPart<K extends keyof TInputs ? TInputs[K] : WebApiDefaultInputs, 'Query'>, WebApiInputPart<K extends keyof TInputs ? TInputs[K] : WebApiDefaultInputs, 'Headers'>>;
};

/** Narrow callbacks keep request objects attached to their owner's stable operation ID. */
export interface WebApiAccessContext {
    readConfiguration(): WebApiClientConfiguration;
    writeConfiguration(value: WebApiClientConfiguration): void;
    readOperation(id: string): WebApiOperation;
    patchOperation(id: string, patch: Partial<Omit<WebApiOperation, 'id'>>): void;
    readBaseUrl(): string;
    writeBaseUrl(value: string): void;
    parameterNames(id: string): readonly string[];
    readParameter(id: string, name: string): WebApiParameterValue | undefined;
    writeParameter(id: string, name: string, value: WebApiParameterValue | undefined): void;
    readParameterType(id: string, name: string): WebApiTemplateParameterType;
    writeParameterType(id: string, name: string, type: WebApiTemplateParameterType): void;
    clearParameters(id: string): void;
    readQuery(id: string, name: string): WebApiQueryValue;
    writeQuery(id: string, name: string, value: WebApiQueryValue): void;
    headerNames(id?: string): readonly string[];
    readHeader(name: string, id?: string): string | undefined;
    writeHeader(name: string, value: string | undefined, id?: string): void;
    readResponseType(id: string): WebApiResponseType;
    writeResponseType(id: string, value: WebApiResponseType): void;
    readState(id: string): WebApiOperationState;
    execute(id: string, options: WebApiRequestOptions): Promise<unknown>;
    bodyParameters(id: string): readonly WebApiTemplateParameter[];
}

/** A FireDAC-style named parameter, backed by the owning runtime request. */
export class WebApiNamedParameter {
    private readonly context;
    private readonly operationId;
    readonly Name: string;
    constructor(context: WebApiAccessContext, operationId: string, Name: string);
    get Value(): WebApiParameterValue | undefined;
    set Value(value: WebApiParameterValue | undefined);
    get Type(): WebApiTemplateParameterType;
    set Type(value: WebApiTemplateParameterType);
    Clear(): void;
}

export class WebApiBodySettings {
    private readonly context;
    private readonly operationId;
    constructor(context: WebApiAccessContext, operationId: string);
    get Kind(): WebApiBodyKind;
    set Kind(value: WebApiBodyKind);
    get Value(): string;
    set Value(value: string);
    get Parameters(): readonly WebApiTemplateParameter[];
    set Parameters(value: readonly WebApiTemplateParameter[]);
}

export class WebApiRequestSettings {
    private readonly context;
    private readonly operationId;
    constructor(context: WebApiAccessContext, operationId: string);
    get Credentials(): WebApiCredentials;
    set Credentials(value: WebApiCredentials);
    get Timeout(): number | null;
    set Timeout(value: number | null);
    get ResponseType(): WebApiResponseType;
    set ResponseType(value: WebApiResponseType);
}

export class WebApiResponse<T = unknown> {
    private readonly context;
    private readonly operationId;
    constructor(context: WebApiAccessContext, operationId: string);
    get Value(): T | undefined;
    get Status(): WebApiOperationState['status'];
    get Error(): unknown;
    get UpdatedAt(): number | undefined;
    get Schema(): WebApiResponseSchema | null;
    set Schema(value: WebApiResponseSchema | null);
}

export class WebApiConnectionSettings<THeaders extends object = Record<string, string>> {
    private readonly context;
    readonly Headers: WebApiHeaderValues<THeaders>;
    constructor(context: WebApiAccessContext);
    get Mode(): WebApiConnection;
    set Mode(value: WebApiConnection);
    get BaseURL(): string;
    set BaseURL(value: string);
    get Timeout(): number;
    set Timeout(value: number);
    get DefaultHeaders(): readonly WebApiParameter[];
    set DefaultHeaders(value: readonly WebApiParameter[]);
}

/** Stable request object with mutable settings and private per-instance parameter values. */
export class WebApiRequest<TParameters extends object = Record<string, WebApiTemplateValue>, TResult = unknown, TQuery extends object = Record<string, WebApiQueryValue>, THeaders extends object = Record<string, string>> {
    private readonly context;
    readonly ID: string;
    readonly parameter: WebApiParameterValues<TParameters>;
    readonly Query: WebApiQueryValues<TQuery>;
    readonly Headers: WebApiHeaderValues<THeaders>;
    readonly Body: WebApiBodySettings;
    readonly Options: WebApiRequestSettings;
    readonly Response: WebApiResponse<TResult>;
    constructor(context: WebApiAccessContext, ID: string);
    get Name(): string;
    set Name(value: string);
    get Method(): string;
    set Method(value: string);
    get Endpoint(): string;
    set Endpoint(value: string);
    get ApiVersion(): number | null;
    set ApiVersion(value: number | null);
    get Definition(): WebApiOperation;
    set Definition(value: WebApiOperation);
    ParamByName(name: string): WebApiNamedParameter;
    ClearParameters(): void;
    /** Executes this request without changing the client's selected Operation first. */
    execute(options?: WebApiRequestOptions): Promise<TResult>;
}

/** Names that must never turn an API client into a thenable or replace object behavior. */
export const WEB_API_REQUEST_RESERVED_NAMES: readonly [
    "then",
    "constructor",
    "__proto__",
    "prototype",
    "toString",
    "toLocaleString",
    "valueOf",
    "hasOwnProperty",
    "isPrototypeOf",
    "propertyIsEnumerable",
    "__defineGetter__",
    "__defineSetter__",
    "__lookupGetter__",
    "__lookupSetter__"
];

/** Named request access with the client's existing public members protected. */
export type WebApiClientInstance<TOutputs extends object = Record<string, unknown>, TInputs extends object = Record<string, WebApiDefaultInputs>, TDefaultHeaders extends object = Record<string, string>> = WebApiClient<TOutputs, TInputs, TDefaultHeaders> & (string extends keyof TOutputs ? object : Pick<WebApiRequests<TOutputs, TInputs>, Exclude<keyof TOutputs & string, keyof WebApiClient<TOutputs, TInputs, TDefaultHeaders> | (typeof WEB_API_REQUEST_RESERVED_NAMES)[number]>>);

export type QueryValue = string | number | boolean | null | undefined;

/** Shared by the browser tester and generated runtime for versioned requests. */
export function apiOperationPath(path: string, version?: number | null): string;

export const WEB_API_RESPONSE_TYPES: readonly [
    "auto",
    "json",
    "text",
    "blob",
    "arrayBuffer"
];

export type WebApiResponseType = (typeof WEB_API_RESPONSE_TYPES)[number];

export type WebApiBodyKind = 'none' | 'json' | 'text' | 'form-urlencoded' | 'form-data';

export type WebApiConnection = 'custom' | 'restgo-session' | 'restgo-api-token' | 'restgo-public';

export type WebApiCredentials = 'omit' | 'same-origin' | 'include';

export type WebApiOperationStatus = 'idle' | 'loading' | 'success' | 'error';

/** Structural, browser-safe counterpart of a persisted API parameter. */
export interface WebApiParameter {
    readonly id: string;
    readonly name: string;
    readonly value: string;
    readonly enabled: boolean;
}

export interface WebApiRequestBody {
    readonly kind: WebApiBodyKind;
    readonly content: string;
    readonly parameters?: readonly WebApiTemplateParameter[];
}

/** Structural contract consumed at runtime; it intentionally has no IDE dependency. */
export interface WebApiResponseSchemaNode {
    readonly id: string;
    readonly name: string;
    readonly path: string;
    readonly kind: 'field' | 'object' | 'list';
    readonly fieldType: string;
    readonly nullable: boolean;
    readonly children: readonly WebApiResponseSchemaNode[];
}

export interface WebApiResponseSchema {
    readonly version: 1;
    readonly root: WebApiResponseSchemaNode;
}

export interface WebApiOperation {
    readonly id: string;
    readonly name: string;
    readonly method: string;
    readonly path: string;
    readonly apiVersion?: number | null;
    readonly headers: readonly WebApiParameter[];
    readonly query: readonly WebApiParameter[];
    readonly body: WebApiRequestBody;
    readonly credentials: WebApiCredentials;
    readonly timeoutMs: number | null;
    readonly responseSchema: WebApiResponseSchema | null;
}

export interface WebApiClientConfiguration {
    readonly schemaVersion: number;
    /** Omitted in existing projects, which continue to use their custom base URL. */
    readonly connection?: WebApiConnection;
    readonly defaultHeaders: readonly WebApiParameter[];
    readonly timeoutMs: number;
    readonly operations: readonly WebApiOperation[];
}

export interface WebApiRequestOptions extends Omit<RequestInit, 'body' | 'headers' | 'signal'> {
    readonly body?: unknown;
    /** Values supplied to <name> placeholders in the configured body for execute(). */
    readonly parameters?: WebApiTemplateValues;
    readonly headers?: HeadersInit;
    readonly query?: Readonly<Record<string, QueryValue | readonly QueryValue[]>>;
    readonly signal?: AbortSignal | null;
    /** Cancels the request after this duration without changing the component default. */
    readonly timeoutMs?: number | null;
    readonly responseType?: WebApiResponseType;
}

export interface WebApiClientOptions extends WebNonvisualComponentOptions {
    readonly baseUrl?: string;
    /** Programmatic default headers, kept compatible with the original client API. */
    readonly headers?: HeadersInit;
    readonly fetch?: typeof globalThis.fetch;
    /** Configuration materialized by the Project Model for named operations. */
    readonly apiClientConfig?: WebApiClientConfiguration;
}

export interface WebApiOperationState<T = unknown> {
    readonly status: WebApiOperationStatus;
    readonly data?: T;
    readonly error?: unknown;
    readonly updatedAt?: number;
}

/** Details supplied by the WebApiClient request lifecycle events. */
export interface WebApiOperationEventDetail<T = unknown> {
    readonly operation: WebApiOperation;
    readonly state: WebApiOperationState<T>;
}

export class WebApiError<TBody = unknown> extends Error {
    readonly status: number;
    readonly statusText: string;
    readonly url: string;
    readonly body: TBody;
    readonly response: Response;
    constructor(message: string, status: number, statusText: string, url: string, body: TBody, response: Response);
}

export class WebApiTimeoutError extends Error {
    readonly timeoutMs: number;
    readonly url: string;
    constructor(timeoutMs: number, url: string);
}

/** A real shared SDK client or an explicitly supplied, transient test-session source. */
export interface RestGoApiSessionSource {
    readonly baseUrl: string;
    getSession(): Promise<import("@webrad/restgo-sdk").RestGoResult<Pick<import("@webrad/restgo-sdk").RestGoSession, 'token'> | null>>;
}

export interface RestGoApplicationApiSource {
    readonly baseUrl: string;
    readonly apiToken?: string;
}

/**
 * Pins a REST request to the RestGo integration and validates its current user session.
 * The SDK validates/renews the session before the request; raw API tokens never qualify.
 * The optional source lets the IDE test with a transient JWT without persisting it.
 */
export function prepareRestGoApiRequest(endpoint: string, options?: RequestInit, source?: RestGoApiSessionSource): Promise<{
    readonly url: string;
    readonly init: RequestInit;
}>;

/** Prepares public or application-token requests without borrowing a user or admin credential. */
export function prepareRestGoApplicationApiRequest(endpoint: string, authentication: 'public' | 'api-token', options?: RequestInit, source?: RestGoApplicationApiSource): {
    readonly url: string;
    readonly init: RequestInit;
};

/**
 * Browser-safe HTTP client with direct requests and Project-Model backed named
 * operations. The latter retain transient state so future data components can
 * bind to an API result without using the DOM as a data store.
 */
export class WebApiClient<TOutputs extends object = Record<string, unknown>, TInputs extends object = Record<string, WebApiDefaultInputs>, TDefaultHeaders extends object = Record<string, string>> extends WebNonvisualComponent {
    #private;
    constructor(options?: WebApiClientOptions | string);
    /** Typed view of the same instance, used by generated page and reusable code. */
    withRequests(): WebApiClientInstance<TOutputs, TInputs, TDefaultHeaders>;
    get baseUrl(): string;
    set baseUrl(value: string);
    /** Immutable normalized contract configured for this client instance. */
    get apiClientConfig(): WebApiClientConfiguration;
    set apiClientConfig(value: WebApiClientConfiguration);
    get Configuration(): WebApiClientConfiguration;
    set Configuration(value: WebApiClientConfiguration);
    get Connection(): WebApiConnectionSettings<TDefaultHeaders>;
    get Operation(): (keyof TOutputs & string) | undefined;
    set Operation(value: (keyof TOutputs & string) | undefined);
    get Requests(): WebApiRequests<TOutputs, TInputs>;
    get Request(): WebApiRequest<WebApiCombinedInputs<TInputs, 'Parameter'>, TOutputs[keyof TOutputs], WebApiCombinedInputs<TInputs, 'Query'>, WebApiCombinedInputs<TInputs, 'Headers'>>;
    get parameter(): WebApiParameterValues<WebApiCombinedInputs<TInputs, 'Parameter'>>;
    get Query(): WebApiQueryValues<WebApiCombinedInputs<TInputs, 'Query'>>;
    get Headers(): WebApiHeaderValues<WebApiCombinedInputs<TInputs, 'Headers'>>;
    get Body(): WebApiBodySettings;
    get Options(): WebApiRequestSettings;
    get Response(): WebApiResponse<TOutputs[keyof TOutputs]>;
    get Method(): string;
    set Method(value: string);
    get Endpoint(): string;
    set Endpoint(value: string);
    get ApiVersion(): number | null;
    set ApiVersion(value: number | null);
    RequestByName<K extends keyof TOutputs & string>(name: K): WebApiRequests<TOutputs, TInputs>[K];
    RequestByName(name: string): WebApiRequest;
    ParamByName(name: string): WebApiNamedParameter;
    ClearParameters(): void;
    /** Saved operation metadata, safe for a Table or another consumer to inspect. */
    get operations(): readonly WebApiOperation[];
    set operations(value: readonly WebApiOperation[]);
    /** Latest successful data, keyed by the configured operation name. */
    get data(): Readonly<Partial<TOutputs>>;
    /** State of the most recently executed operation. */
    get status(): WebApiOperationStatus;
    get error(): unknown;
    getOperationState<T = unknown>(operationName: string): WebApiOperationState<T>;
    /** Notifies runtime consumers whenever a named operation changes state. */
    subscribe(listener: () => void): () => void;
    request<T>(path: string, options?: WebApiRequestOptions): Promise<T>;
    get<T>(path: string, options?: WebApiRequestOptions): Promise<T>;
    post<T>(path: string, body?: unknown, options?: WebApiRequestOptions): Promise<T>;
    put<T>(path: string, body?: unknown, options?: WebApiRequestOptions): Promise<T>;
    patch<T>(path: string, body?: unknown, options?: WebApiRequestOptions): Promise<T>;
    delete<T>(path: string, options?: WebApiRequestOptions): Promise<T>;
    head(path: string, options?: WebApiRequestOptions): Promise<void>;
    options<T>(path: string, options?: WebApiRequestOptions): Promise<T>;
    execute<K extends keyof TOutputs & string>(operationName: K, options?: WebApiRequestOptions): Promise<TOutputs[K]>;
    execute(options?: WebApiRequestOptions): Promise<TOutputs[keyof TOutputs]>;
    execute<T = unknown>(operationName: string, options?: WebApiRequestOptions): Promise<T>;
    /** Resolves any saved schema node from the latest result of one operation. */
    getOutputById<T = unknown>(operationName: string, schemaNodeIdOrPath: string): T | undefined;
    /** Returns a saved list output, or an empty readonly list when it is unavailable. */
    getList<T = unknown>(operationName: string, schemaNodeIdOrPath: string): readonly T[];
}
